CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, business_name text, business_type text NOT NULL DEFAULT 'hibrido' CHECK (business_type IN ('produto','servico','hibrido')), monthly_income_goal numeric NOT NULL DEFAULT 5000 CHECK(monthly_income_goal>=0), monthly_work_hours numeric NOT NULL DEFAULT 160 CHECK(monthly_work_hours>0), monthly_fixed_costs numeric NOT NULL DEFAULT 0 CHECK(monthly_fixed_costs>=0), hourly_rate numeric NOT NULL DEFAULT 31.25 CHECK(hourly_rate>=0), mp_connected boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profile_owner ON public.profiles FOR ALL TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.create_business_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id) VALUES(NEW.id); RETURN NEW; END; $$;
CREATE TRIGGER create_business_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_business_profile();
CREATE TABLE public.payment_connections (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, access_token text NOT NULL, refresh_token text, mp_user_id text UNIQUE, public_key text, expires_at timestamptz, updated_at timestamptz DEFAULT now());
GRANT ALL ON public.payment_connections TO service_role;
ALTER TABLE public.payment_connections ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.oauth_states (state text PRIMARY KEY, user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL, verifier text NOT NULL);
GRANT ALL ON public.oauth_states TO service_role; ALTER TABLE public.oauth_states ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.inventory_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, name text NOT NULL, category text NOT NULL DEFAULT 'materia_prima' CHECK(category IN ('materia_prima','embalagem','material_servico','revenda')), unit_type text NOT NULL DEFAULT 'g' CHECK(unit_type IN ('g','ml','un','cm')), package_quantity numeric NOT NULL CHECK(package_quantity>0), regular_price numeric NOT NULL CHECK(regular_price>=0), promo_price numeric CHECK(promo_price>=0), is_promo_active boolean NOT NULL DEFAULT false, unit_cost_active numeric GENERATED ALWAYS AS (CASE WHEN is_promo_active AND promo_price>0 THEN promo_price/package_quantity ELSE regular_price/package_quantity END) STORED, unit_cost_regular numeric GENERATED ALWAYS AS(regular_price/package_quantity) STORED, current_stock numeric NOT NULL DEFAULT 0, min_stock_alert numeric NOT NULL DEFAULT 0 CHECK(min_stock_alert>=0), supplier_name text, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.inventory_items TO authenticated; GRANT ALL ON public.inventory_items TO service_role; ALTER TABLE public.inventory_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY inventory_owner ON public.inventory_items FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE INDEX inventory_owner_idx ON public.inventory_items(user_id);
CREATE TABLE public.catalog_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, item_type text NOT NULL CHECK(item_type IN ('produto','servico')), name text NOT NULL, description text, target_audience text, main_benefit text, pain_point_solved text, execution_minutes integer NOT NULL DEFAULT 0 CHECK(execution_minutes>=0), labor_cost numeric NOT NULL DEFAULT 0, materials_cost numeric NOT NULL DEFAULT 0, fixed_cost_allocation numeric NOT NULL DEFAULT 0, total_unit_cost numeric NOT NULL CHECK(total_unit_cost>=0), desired_margin_percent numeric NOT NULL DEFAULT 50, platform_tax_percent numeric NOT NULL DEFAULT 4.99, suggested_price numeric NOT NULL CHECK(suggested_price>0), promo_sale_price numeric CHECK(promo_sale_price>0), is_promo_sale_active boolean NOT NULL DEFAULT false, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.catalog_items TO authenticated; GRANT ALL ON public.catalog_items TO service_role; ALTER TABLE public.catalog_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY catalog_owner ON public.catalog_items FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid()); CREATE INDEX catalog_owner_idx ON public.catalog_items(user_id);
CREATE TABLE public.catalog_recipes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), catalog_item_id uuid NOT NULL REFERENCES public.catalog_items(id) ON DELETE CASCADE, inventory_item_id uuid NOT NULL REFERENCES public.inventory_items(id) ON DELETE RESTRICT, quantity_used numeric NOT NULL CHECK(quantity_used>0), UNIQUE(catalog_item_id,inventory_item_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.catalog_recipes TO authenticated; GRANT ALL ON public.catalog_recipes TO service_role; ALTER TABLE public.catalog_recipes ENABLE ROW LEVEL SECURITY;
CREATE POLICY recipe_owner ON public.catalog_recipes FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.catalog_items c WHERE c.id=catalog_item_id AND c.user_id=auth.uid())) WITH CHECK(EXISTS(SELECT 1 FROM public.catalog_items c WHERE c.id=catalog_item_id AND c.user_id=auth.uid()) AND EXISTS(SELECT 1 FROM public.inventory_items i WHERE i.id=inventory_item_id AND i.user_id=auth.uid()));
CREATE TABLE public.orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, catalog_item_id uuid NOT NULL REFERENCES public.catalog_items(id) ON DELETE RESTRICT, customer_name text NOT NULL, customer_whatsapp text, quantity integer NOT NULL DEFAULT 1 CHECK(quantity>0), unit_price_charged numeric NOT NULL CHECK(unit_price_charged>0), total_amount numeric NOT NULL CHECK(total_amount>0), total_cost_snapshot numeric NOT NULL, payment_method text NOT NULL CHECK(payment_method IN ('mp_checkout_pro','manual_pix','manual_dinheiro','manual_cartao')), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','paid','cancelled')), mp_preference_id text, mp_payment_id text UNIQUE, checkout_url text, stock_deducted boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), paid_at timestamptz);
GRANT SELECT ON public.orders TO authenticated; GRANT ALL ON public.orders TO service_role; ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY; CREATE POLICY orders_read_owner ON public.orders FOR SELECT TO authenticated USING(user_id=auth.uid()); CREATE INDEX orders_owner_date_idx ON public.orders(user_id,created_at);
CREATE TABLE public.cashflow_transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, order_id uuid UNIQUE REFERENCES public.orders(id) ON DELETE RESTRICT, type text NOT NULL CHECK(type IN ('entrada','saida')), category text NOT NULL CHECK(category IN ('venda_produto','venda_servico','compra_insumo','custo_fixo','marketing','pro_labore','outros')), description text NOT NULL, amount numeric NOT NULL CHECK(amount>0), transaction_date date NOT NULL DEFAULT current_date, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.cashflow_transactions TO authenticated; GRANT ALL ON public.cashflow_transactions TO service_role; ALTER TABLE public.cashflow_transactions ENABLE ROW LEVEL SECURITY; CREATE POLICY cash_read ON public.cashflow_transactions FOR SELECT TO authenticated USING(user_id=auth.uid()); CREATE POLICY cash_expense ON public.cashflow_transactions FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND type='saida' AND order_id IS NULL); CREATE INDEX cash_owner_date_idx ON public.cashflow_transactions(user_id,transaction_date);
CREATE FUNCTION public.paid_order_effects() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r record; BEGIN IF NEW.status='paid' AND NOT NEW.stock_deducted THEN FOR r IN SELECT cr.inventory_item_id,cr.quantity_used FROM public.catalog_recipes cr WHERE cr.catalog_item_id=NEW.catalog_item_id ORDER BY cr.inventory_item_id LOOP UPDATE public.inventory_items SET current_stock=current_stock-r.quantity_used*NEW.quantity,updated_at=now() WHERE id=r.inventory_item_id AND user_id=NEW.user_id; END LOOP; INSERT INTO public.cashflow_transactions(user_id,order_id,type,category,description,amount) SELECT NEW.user_id,NEW.id,'entrada',CASE WHEN c.item_type='produto' THEN 'venda_produto' ELSE 'venda_servico' END,c.name || ' · ' || NEW.customer_name,NEW.total_amount FROM public.catalog_items c WHERE c.id=NEW.catalog_item_id ON CONFLICT(order_id) DO NOTHING; NEW.stock_deducted=true; NEW.paid_at=now(); END IF; RETURN NEW; END; $$;
CREATE TRIGGER paid_order_effects BEFORE INSERT OR UPDATE ON public.orders FOR EACH ROW EXECUTE FUNCTION public.paid_order_effects();
CREATE FUNCTION public.process_paid_order(p_order_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.orders SET status='paid' WHERE id=p_order_id AND status='pending' AND stock_deducted=false; END; $$;
REVOKE ALL ON FUNCTION public.process_paid_order(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.process_paid_order(uuid) TO service_role;
CREATE FUNCTION public.create_sale(p_item uuid,p_customer text,p_whatsapp text,p_quantity integer,p_promo boolean,p_method text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.catalog_items; new_id uuid; price numeric; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Acesso necessário'; END IF; IF p_quantity<1 OR p_quantity>100000 OR length(p_customer)<1 OR length(p_customer)>200 OR p_method NOT IN ('mp_checkout_pro','manual_pix','manual_dinheiro','manual_cartao') THEN RAISE EXCEPTION 'Dados inválidos'; END IF; SELECT * INTO c FROM public.catalog_items WHERE id=p_item AND user_id=auth.uid() AND active; IF NOT FOUND THEN RAISE EXCEPTION 'Item não encontrado'; END IF; price=CASE WHEN p_promo AND c.promo_sale_price>0 THEN c.promo_sale_price ELSE c.suggested_price END; INSERT INTO public.orders(user_id,catalog_item_id,customer_name,customer_whatsapp,quantity,unit_price_charged,total_amount,total_cost_snapshot,payment_method,status) VALUES(auth.uid(),c.id,p_customer,p_whatsapp,p_quantity,price,price*p_quantity,c.total_unit_cost*p_quantity,p_method,CASE WHEN p_method='mp_checkout_pro' THEN 'pending' ELSE 'paid' END) RETURNING id INTO new_id; RETURN new_id; END; $$;
REVOKE ALL ON FUNCTION public.create_sale(uuid,text,text,integer,boolean,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.create_sale(uuid,text,text,integer,boolean,text) TO authenticated;
CREATE FUNCTION public.restock_item(p_id uuid,p_quantity numeric,p_promo boolean,p_expense boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i public.inventory_items; BEGIN SELECT * INTO i FROM public.inventory_items WHERE id=p_id AND user_id=auth.uid() FOR UPDATE; IF NOT FOUND OR p_quantity<=0 THEN RAISE EXCEPTION 'Reposição inválida'; END IF; UPDATE public.inventory_items SET current_stock=current_stock+p_quantity,is_promo_active=p_promo,updated_at=now() WHERE id=p_id; IF p_expense THEN INSERT INTO public.cashflow_transactions(user_id,type,category,description,amount) VALUES(auth.uid(),'saida','compra_insumo','Reposição · '||i.name,p_quantity*CASE WHEN p_promo AND i.promo_price>0 THEN i.promo_price/i.package_quantity ELSE i.unit_cost_regular END); END IF; END; $$;
REVOKE ALL ON FUNCTION public.restock_item(uuid,numeric,boolean,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.restock_item(uuid,numeric,boolean,boolean) TO authenticated;
ALTER PUBLICATION supabase_realtime ADD TABLE public.orders,public.inventory_items,public.cashflow_transactions,public.catalog_items;